import \'package:flutter/material.dart\';\n\nclass SettingsPage extends StatefulWidget {\n  const SettingsPage({super.key});\n\n  @override\n  State<SettingsPage> createState() => _SettingsPageState();\n}\n\nclass _SettingsPageState extends State<SettingsPage> {\n  double _narrationSpeed = 1.0;\n  double _textSize = 1.0;\n  bool _highContrast = false;\n  bool _screenReader = false;\n  bool _darkMode = false;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text(\'Settings\', style: TextStyle(fontWeight: FontWeight.bold)),\n        centerTitle: true,\n        backgroundColor: Colors.white,\n        elevation: 0,\n        leading: IconButton(\n          icon: const Icon(Icons.arrow_back_ios, color: Colors.black),\n          onPressed: () => Navigator.of(context).pop(),\n        ),\n      ),\n      backgroundColor: Colors.white,\n      body: SingleChildScrollView(\n        child: Padding(\n          padding: const EdgeInsets.all(16.0),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              _buildSectionTitle(\'General\'),\n              _buildGeneralSettings(),\n              const SizedBox(height: 24),\n              _buildSectionTitle(\'App Preferences\'),\n              _buildAppPreferences(),\n              const SizedBox(height: 24),\n              _buildSectionTitle(\'Account & Support\'),\n              _buildAccountSupport(),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildSectionTitle(String title) {\n    return Padding(\n      padding: const EdgeInsets.only(bottom: 8.0),\n      child: Text(title, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),\n    );\n  }\n\n  Widget _buildGeneralSettings() {\n    return Card(\n      elevation: 2,\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n      child: Column(\n        children: [\n          _buildSettingItem(icon: Icons.language, title: \'Language & Voice\', subtitle: \'English (US)\', trailing: const Text(\'English (US)\')),\n          _buildSliderSetting(title: \'Narration Speed\', value: _narrationSpeed, min: 0.5, max: 2.0, divisions: 3, label: \'\${_narrationSpeed.toStringAsFixed(1)}x\', onChanged: (val) => setState(() => _narrationSpeed = val)),\n          _buildSliderSetting(title: \'Text Size\', value: _textSize, min: 0.8, max: 1.5, divisions: 7, label: \'\${(_textSize * 100).toInt()}%\', onChanged: (val) => setState(() => _textSize = val)),\n          _buildSwitchSetting(title: \'High Contrast Mode\', subtitle: \'Enhance readability for visual impairment\', value: _highContrast, onChanged: (val) => setState(() => _highContrast = val)),\n          _buildSwitchSetting(title: \'Screen Reader Support\', subtitle: \'Enable compatibility with screen readers\', value: _screenReader, onChanged: (val) => setState(() => _screenReader = val)),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildAppPreferences() {\n    return Card(\n      elevation: 2,\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n      child: Column(\n        children: [\n          _buildSettingItem(icon: Icons.map_outlined, title: \'Offline Guides & Maps\', subtitle: \'Manage downloaded content\'),\n          _buildSettingItem(icon: Icons.notifications_outlined, title: \'Notifications\', subtitle: \'Control alerts and sounds\'),\n          _buildSwitchSetting(title: \'Dark Mode\', subtitle: \'Switch between light and dark themes\', value: _darkMode, onChanged: (val) => setState(() => _darkMode = val)),\n          _buildSettingItem(icon: Icons.attach_money, title: \'Currency & Units\', subtitle: \'Set preferred currency and measurement units\'),\n          _buildSettingItem(icon: Icons.lock_outline, title: \'PIN/Biometric Lock\', subtitle: \'Secure your app with a PIN or fingerprint/face ID\'),\n          _buildSettingItem(icon: Icons.shield_outlined, title: \'Permissions\', subtitle: \'Review app access to device features\'),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildAccountSupport() {\n    return Card(\n      elevation: 2,\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n      child: Column(\n        children: [\n          _buildSettingItem(icon: Icons.cleaning_services_outlined, title: \'Clear Cache\', subtitle: \'Free up storage space\'),\n          _buildSettingItem(icon: Icons.help_outline, title: \'Help & Support\', trailing: const Icon(Icons.arrow_forward_ios), onTap: () => Navigator.pushNamed(context, \'services\')),\n          _buildSettingItem(icon: Icons.info_outline, title: \'About SafePath Connect\', trailing: const Icon(Icons.arrow_forward_ios), onTap: () => Navigator.pushNamed(context, \'about\')),\n          _buildSettingItem(icon: Icons.delete_outline, title: \'Delete Account\', titleColor: Colors.red, onTap: () {}),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildSettingItem({required IconData icon, required String title, String? subtitle, Widget? trailing, Color? titleColor, VoidCallback? onTap}) {\n    return ListTile(\n      leading: Icon(icon),\n      title: Text(title, style: TextStyle(color: titleColor)),\n      subtitle: subtitle != null ? Text(subtitle) : null,\n      trailing: trailing,\n      onTap: onTap,\n    );\n  }\n\n  Widget _buildSliderSetting({required String title, required double value, required double min, required double max, required int divisions, required String label, required ValueChanged<double> onChanged}) {\n    return ListTile(\n      title: Text(title),\n      subtitle: Slider(\n        value: value,\n        min: min,\n        max: max,\n        divisions: divisions,\n        label: label,\n        onChanged: onChanged,\n      ),\n    );\n  }\n\n  Widget _buildSwitchSetting({required String title, required String subtitle, required bool value, required ValueChanged<bool> onChanged}) {\n    return SwitchListTile(\n      title: Text(title),\n      subtitle: Text(subtitle),\n      value: value,\n      onChanged: onChanged,\n    );\n  }\n}\n